using System;
using System.Collections.Generic;
using System.Linq;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using RogControl;
public static class KeyboardViewsGuiTests {
 static BindingFlags H=BindingFlags.NonPublic|BindingFlags.Instance;
 static int checks;
 static void Check(bool ok,string message){checks++;if(!ok)throw new Exception(message);}
 static object Get(MainWindow w,string name){return typeof(MainWindow).GetField(name,H).GetValue(w);}
 static void Set(MainWindow w,string name,object value){typeof(MainWindow).GetField(name,H).SetValue(w,value);}
 static object Call(MainWindow w,string name,params object[] args){return typeof(MainWindow).GetMethod(name,H).Invoke(w,args);}
 static IEnumerable<DependencyObject> Walk(DependencyObject n){yield return n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var c in Walk(VisualTreeHelper.GetChild(n,i)))yield return c;}
 static Dictionary<string,object> Obj(params object[] v){var m=new Dictionary<string,object>();for(int i=0;i<v.Length;i+=2)m[(string)v[i]]=v[i+1];return m;}
 static FrameworkElement Render(MainWindow w,string tab,int width){((Dictionary<string,string>)Get(w,"gearTabs"))["keyboard"]=tab;Call(w,"ShowPage","device:keyboard");var f=(FrameworkElement)w.Content;f.Measure(new Size(width,826));f.Arrange(new Rect(0,0,width,826));f.UpdateLayout();((ScrollViewer)Get(w,"pageScroll")).ScrollToTop();f.UpdateLayout();var bitmap=new RenderTargetBitmap(width,826,96,96,PixelFormats.Pbgra32);bitmap.Render(f);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"keyboard-"+width+"-"+tab+"-synthetic.png")))png.Save(output);return f;}
 [STAThread] public static void Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var w=new MainWindow(true);var state=Obj("deviceId","synthetic-keyboard","online",true,"readbackConfirmed",true,"setCapabilities",new[]{"leverMode","leverModeEnabled","keyBinding","oledEnabled","oledMode","oledModeEnabled","oledPreset","oledBrightness","oledBarItem","oledKpsEnabled"},"settingOptions",Obj("keySources",new[]{"KeyA","LeverUp","LeverMid","LeverDown"},"keyTargets",new[]{"Default","KeyA","AV_VolUp","AV_VolDown"},"oledBarItems",new[]{"CapsLock","BatteryStatus"}),"snapshot",Obj("leverMode",0,"leverModeStates",new[]{true,true,true,true,true,false,false,true},"oledEnabled",true,"oledBrightness",75,"oledMode",0,"oledModeStates",new[]{true,false,false,false,true},"oledPreset",2,"oledKpsEnabled",true,"oledBarInfo",Obj("CapsLock",true,"BatteryStatus",true),"profileInformationUnconfirmed",false,"profileCount",1,"activeProfile",0,"keyBinding",Obj("source","LeverUp","target","AV_VolUp")));((Dictionary<string,Dictionary<string,object>>)Get(w,"gearStates"))["keyboard"]=state;
 foreach(int width in new[]{1180,1538,2560})foreach(string tab in new[]{"按键","拨杆","OLED"}){var frame=Render(w,tab,width);var nodes=Walk(frame).ToArray();var scroll=(ScrollViewer)Get(w,"pageScroll");double origin=scroll.TransformToAncestor(frame).Transform(new Point()).Y;Console.WriteLine(tab+" "+width+" body origin="+origin);Check(((StackPanel)Get(w,"fixedPageHeader")).Children.Count==2,"Pinned keyboard title/tab strip");Check(!nodes.OfType<Image>().Any(),"No product image inserted into keyboard view");Check(nodes.OfType<Button>().Where(b=>Convert.ToString(b.Content)=="应用").All(b=>!b.IsEnabled),"No render apply action enabled");foreach(var label in Walk(scroll.Content as DependencyObject).OfType<TextBlock>().Where(t=>t.ActualWidth>0)){var x=label.TransformToAncestor(frame).Transform(new Point()).X;if(tab!="按键")Check(x>=248&&x+label.ActualWidth<=width-10,"View text fits horizontal body "+width+"/"+tab+"/"+label.Text);}if(tab=="OLED"){var draft=(KeyboardViewsDraft)Get(w,"keyboardViewsDraft");Check(draft.OledView==0,"Observed custom OLED category");Check(!nodes.OfType<TextBlock>().Any(t=>t.Text=="笔记本电量"),"Notebook battery category omitted for this model");}if(tab=="拨杆")Check(nodes.OfType<TextBlock>().Any(t=>t.Text=="主板风扇控制"),"Unavailable fan mode keeps its original position");}
 var lever=Walk(Render(w,"拨杆",1538)).ToArray();var media=lever.OfType<Button>().First(b=>b.Content is Grid&&Walk((Grid)b.Content).OfType<TextBlock>().Any(t=>t.Text=="媒体曲目"));media.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));var d=(KeyboardViewsDraft)Get(w,"keyboardViewsDraft");Check(d.LeverMode==1&&d.Dirty.Contains("leverMode"),"Choosing lever function edits draft only");Check(Convert.ToInt32(((Dictionary<string,object>)state["snapshot"])["leverMode"])==0,"Observed lever mode remains unchanged");Set(w,"busy",true);media.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(d.LeverMode==1,"Busy stale function cannot alter draft");Set(w,"busy",false);var worker=(WorkerClient)Get(w,"gearWorker");Check(typeof(WorkerClient).GetField("process",H).GetValue(worker)==null,"No GUI operation started worker");
 d.Dirty.Clear();d.LeverView=7;var custom=Walk(Render(w,"拨杆",1538)).ToArray();var selector=custom.OfType<ComboBox>().First(c=>c.IsEnabled);selector.SelectedIndex=2;Check(d.Dirty.Contains("leverBinding:LeverUp"),"Custom binding changes are local drafts");Check(typeof(WorkerClient).GetField("process",H).GetValue(worker)==null,"Binding selection never sends native write");var plan=Call(w,"KeyboardViewCommands","lever",state,d);Check(plan!=null,"Verified dirty binding forms plan without native I/O");d.Dirty.Add("leverFlag:5");d.LeverFlags["5"]=true;bool rejected=false;try{Call(w,"KeyboardViewCommands","lever",state,d);}catch(TargetInvocationException e){rejected=e.InnerException is ArgumentException;}Check(rejected,"Unsupported final fan flag rejects whole plan before any native write");
 ((Dictionary<string,Dictionary<string,object>>)Get(w,"gearStates"))["keyboard"]=Obj("deviceId","synthetic-keyboard","online",false,"snapshot",state["snapshot"]);Set(w,"keyboardViewsDraft",null);var offline=Walk(Render(w,"OLED",1180)).ToArray();Check(offline.OfType<Slider>().All(s=>!s.IsEnabled),"Offline values cannot enable slider");Check((string)Call(w,"OriginalGearProfileName",((Dictionary<string,Dictionary<string,object>>)Get(w,"gearStates"))["keyboard"],"keyboard")=="配置文件 —","Offline profile hides stale confirmed value");Check((string)Call(w,"OriginalGearProfileName",state,"keyboard")=="默认配置文件","Confirmed zero keyboard profile means default");Console.WriteLine("Keyboard Views GUI: "+checks+" checks; synthetic data, no device worker.");app.Shutdown();}
}
